package com.indiesoundquest.conversation.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="conversation_message") public class ConversationMessage {
 @Id private UUID id; @Column(name="conversation_id",nullable=false) private UUID conversationId; @Column(name="client_message_id") private UUID clientMessageId; @Column(name="agent_run_id") private UUID agentRunId; @Enumerated(EnumType.STRING) @Column(nullable=false) private ConversationMessageRole role; @Enumerated(EnumType.STRING) @Column(nullable=false) private ConversationMessageType type; @Column(name="text_content",columnDefinition="LONGTEXT") private String textContent; @Column(name="card_type") private String cardType; @Column(name="card_payload_json",columnDefinition="JSON") private String cardPayloadJson; @Enumerated(EnumType.STRING) @Column(nullable=false) private ConversationMessageStatus status; @Column(name="sequence_number",nullable=false) private long sequenceNumber; @Column(name="created_at",nullable=false) private Instant createdAt; @Column(name="completed_at") private Instant completedAt;
 protected ConversationMessage(){} private ConversationMessage(UUID id,UUID c,UUID client,UUID run,ConversationMessageRole r,ConversationMessageType t,String text,long seq,ConversationMessageStatus s){this.id=id;conversationId=c;clientMessageId=client;agentRunId=run;role=r;type=t;textContent=text;sequenceNumber=seq;status=s;createdAt=Instant.now();if(s==ConversationMessageStatus.COMPLETED)completedAt=createdAt;} public static ConversationMessage user(UUID c,UUID client,String text,long seq){return new ConversationMessage(UUID.randomUUID(),c,client,null,ConversationMessageRole.USER,ConversationMessageType.USER_TEXT,text,seq,ConversationMessageStatus.COMPLETED);} public static ConversationMessage run(UUID c,UUID run,long seq){return new ConversationMessage(UUID.randomUUID(),c,null,run,ConversationMessageRole.ASSISTANT,ConversationMessageType.AGENT_RUN,null,seq,ConversationMessageStatus.RUNNING);} public static ConversationMessage assistant(UUID c,UUID run,String text,long seq){return new ConversationMessage(UUID.randomUUID(),c,null,run,ConversationMessageRole.ASSISTANT,ConversationMessageType.AGENT_TEXT,text,seq,ConversationMessageStatus.COMPLETED);} public static ConversationMessage card(UUID c,UUID client,ConversationMessageType type,String cardType,String payload,long seq){var m=new ConversationMessage(UUID.randomUUID(),c,client,null,ConversationMessageRole.ASSISTANT,type,null,seq,ConversationMessageStatus.COMPLETED);m.cardType=cardType;m.cardPayloadJson=payload;return m;} public static ConversationMessage system(UUID c,String text,long seq){return new ConversationMessage(UUID.randomUUID(),c,null,null,ConversationMessageRole.SYSTEM,ConversationMessageType.SYSTEM_NOTE,text,seq,ConversationMessageStatus.COMPLETED);} public UUID getId(){return id;} public UUID getClientMessageId(){return clientMessageId;} public UUID getAgentRunId(){return agentRunId;} public ConversationMessageRole getRole(){return role;} public ConversationMessageType getType(){return type;} public String getTextContent(){return textContent;} public String getCardType(){return cardType;} public String getCardPayloadJson(){return cardPayloadJson;} public ConversationMessageStatus getStatus(){return status;} public long getSequenceNumber(){return sequenceNumber;} public Instant getCreatedAt(){return createdAt;} public void complete(){status=ConversationMessageStatus.COMPLETED;completedAt=Instant.now();} public void fail(){status=ConversationMessageStatus.FAILED;completedAt=Instant.now();}
}
